from taf.rfrl.procedures.resources.python.logger import log_input_and_output

from taf.rfrl.procedures.resources.python.sw_stream.SwStreamSingleton import \
    SwStreamSingleton


@log_input_and_output
def get_sw_stream(device='GNB'):
    """
    Gets software stream

    :param device: can be GNB or ENB, gives information whether sw_stream should be taken from gNB or eNB.
                   GNB by default.
    :type device: str
    :return: Returns stream of given software

                e.g:
                    Sw on bts: 5G21A_0.800.xxx

                    output:  '5G21A'
    :rtype: str
    """
    return SwStreamSingleton().get_sw_stream(translate_master=False, device=device)


@log_input_and_output
def get_sw_stream_with_translated_master(bts_type='GNB'):
    """
    Gets software stream
    :param bts_type: can be GNB or ENB, gives information whether sw_stream should be taken from gNB or eNB.
                     GNB by default.
    :type bts_type: str

    :return: Returns stream of given software

                e.g:
                    Sw on bts: 5G21A_0.800.xxx

                    output:  'master'
    :rtype: str
    """
    return SwStreamSingleton().get_sw_stream(translate_master=True, device=bts_type)
